namespace CrashEvidenceCollector.Core;

/// <summary>
/// Broad grouping for a stop code, so incidents can be counted, coloured and
/// filtered by the part of Windows that reported them rather than by raw number.
/// The family says who <em>detected</em> the fault; it never claims who caused it.
/// </summary>
public enum BugCheckFamily
{
    Unknown,
    Memory,
    Driver,
    Storage,
    FileSystem,
    Hardware,
    Graphics,
    Power,
    Security,
    Boot,
    Process,
    Network,
    Usb,
    Virtualization,
    Verifier,
    Kernel
}

/// <summary>A stop code with a name, a plain-English title and one honest sentence.</summary>
public sealed record BugCheckSummary(ulong Code, string Name, string PlainTitle, string Meaning, BugCheckFamily Family)
{
    public string HexCode => $"0x{Code:X}";
}

/// <summary>
/// Breadth-first stop-code vocabulary. <see cref="BugCheckKnowledge"/> holds the
/// deep, parameter-level analysis for the codes this app can genuinely reason
/// about; this catalogue exists so that every <em>other</em> code still gets a
/// name and a sentence instead of raw hexadecimal.
///
/// Entries state documented Windows semantics only. Where a name is misleading
/// — MEMORY_MANAGEMENT does not mean "your RAM is faulty" — the sentence says so,
/// because the wrong plain-English answer is worse than none.
/// </summary>
public static class BugCheckCatalog
{
    private static BugCheckSummary B(ulong code, string name, string title, string meaning, BugCheckFamily family) => new(code, name, title, meaning, family);

