    /// <summary>Looks up a stop code. Returns null rather than guessing.</summary>
    public static BugCheckSummary? Find(ulong code) => Catalog.TryGetValue(code, out var summary) ? summary : null;

    public static IReadOnlyCollection<BugCheckSummary> All => (IReadOnlyCollection<BugCheckSummary>)Catalog.Values;

    /// <summary>How many stop codes this build can name. Surfaced in the help pane.</summary>
    public static int Count => Catalog.Count;

    public static string FamilyLabel(BugCheckFamily family) => family switch
    {
        BugCheckFamily.Memory => "Memory",
        BugCheckFamily.Driver => "Driver",
        BugCheckFamily.Storage => "Storage",
        BugCheckFamily.FileSystem => "File system",
        BugCheckFamily.Hardware => "Hardware",
        BugCheckFamily.Graphics => "Graphics",
        BugCheckFamily.Power => "Power",
        BugCheckFamily.Security => "Security / integrity",
        BugCheckFamily.Boot => "Startup",
        BugCheckFamily.Process => "Critical process",
        BugCheckFamily.Network => "Network",
        BugCheckFamily.Usb => "USB",
        BugCheckFamily.Virtualization => "Virtualisation",
        BugCheckFamily.Verifier => "Driver Verifier",
        BugCheckFamily.Kernel => "Kernel",
        _ => "Unclassified"
    };
